SELECT "rag_chunk"."id", "rag_chunk"."document_id", "rag_chunk"."chunk_index", "rag_chunk"."content", "rag_chunk"."content_hash", "rag_chunk"."token_count", "rag_chunk"."metadata", "rag_chunk"."embedding_id", "rag_chunk"."embedding_model", "rag_chunk"."embedding_version", "rag_chunk"."created_time", ("rag_document"."metadata" ->> 'problem_id') AS "bound_problem", ("rag_document"."metadata" ->> 'knowledge_id') AS "bound_knowledge", ts_rank(to_tsvector('simple'::regconfig, COALESCE("rag_chunk"."content", '')), plainto_tsquery('simple'::regconfig, 'binary invariant')) AS "rank", "rag_document"."id", "rag_document"."title", "rag_document"."source_type", "rag_document"."source_id", "rag_document"."source_url", "rag_document"."content", "rag_document"."content_hash", "rag_document"."access_scope", "rag_document"."status", "rag_document"."metadata", "rag_document"."created_time", "rag_document"."updated_time" FROM "rag_chunk" INNER JOIN "rag_document" ON ("rag_chunk"."document_id" = "rag_document"."id") WHERE (("rag_document"."metadata" -> 'knowledge_id') = '1' AND "rag_document"."access_scope" IN ('public', 'student') AND "rag_document"."status" = 'active' AND NOT ("rag_document"."source_type" = 'solution') AND (("rag_document"."metadata" ->> 'problem_id') IS NULL OR ("rag_document"."metadata" ->> 'problem_id') IN (SELECT U0."_id" FROM "problem" U0 WHERE (U0."contest_id" IS NULL AND U0."visible"))) AND (("rag_document"."metadata" ->> 'knowledge_id') IS NULL OR ("rag_document"."metadata" ->> 'knowledge_id') IN (SELECT CAST(U0."id" AS varchar) AS "text_id" FROM "knowledge_point" U0 WHERE U0."status" = 'active')) AND "rag_chunk"."id" IN ((SELECT "rag_chunk"."id" FROM "rag_chunk" WHERE to_tsvector('simple'::regconfig, COALESCE("rag_chunk"."content", '')) @@ plainto_tsquery('simple'::regconfig, 'binary invariant')) UNION (SELECT "rag_chunk"."id" FROM "rag_chunk" WHERE UPPER("rag_chunk"."content"::text) LIKE UPPER('%binary invariant%')))) ORDER BY "rank" DESC, "rag_chunk"."id" ASC LIMIT 5;
